import type Database from 'better-sqlite3';

export interface Migration {
  version: number;
  description: string;
  up(db: Database.Database): void;
}

export interface MigrationResult {
  fromVersion: number;
  toVersion: number;
  applied: number[];
}

function assertUniqueVersions(migrations: readonly Migration[]): void {
  const seen = new Set<number>();
  for (const m of migrations) {
    if (seen.has(m.version)) throw new Error(`Duplicate migration version: ${m.version}`);
    seen.add(m.version);
  }
}

/** Run pending migrations inside one transaction and record applied versions. */
export function runMigrations(db: Database.Database, migrations: readonly Migration[]): MigrationResult {
  assertUniqueVersions(migrations);
  db.exec(`
    CREATE TABLE IF NOT EXISTS _schema_migrations (
      version INTEGER PRIMARY KEY,
      description TEXT NOT NULL DEFAULT '',
      applied_at TEXT NOT NULL DEFAULT (datetime('now'))
    )
  `);

  const row = db.prepare('SELECT COALESCE(MAX(version), 0) AS version FROM _schema_migrations').get() as { version: number };
  const fromVersion = Number(row.version ?? 0);
  const pending = [...migrations].sort((a, b) => a.version - b.version).filter((m) => m.version > fromVersion);
  const applied: number[] = [];

  if (pending.length > 0) {
    const tx = db.transaction(() => {
      const record = db.prepare('INSERT INTO _schema_migrations (version, description) VALUES (?, ?)');
      for (const migration of pending) {
        migration.up(db);
        record.run(migration.version, migration.description);
        applied.push(migration.version);
      }
    });
    tx();
  }

  const toVersion = applied.length > 0 ? applied[applied.length - 1]! : fromVersion;
  return { fromVersion, toVersion, applied };
}

