/**
 * Scenario-outcomes store lifecycle.
 *
 * recordScenarioPrediction and getCalibrationFeedback used to open a
 * fresh SQLite handle through createDatabase(dbPath) on every call,
 * never closing it. analyze.ts calls recordScenarioPrediction once per
 * scenario, so a typical run leaked ~10 handles.
 *
 * The fix lazy-caches the store on first use and closes it inside
 * service.close(). This test pins both behaviours:
 *   1. createScenarioOutcomeStore is invoked at most once per service
 *      across many record calls.
 *   2. service.close() releases the cached store.
 */
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { mkdtempSync, rmSync } from 'node:fs';
import { Logger } from 'shared/logger.js';

let tmpDir: string;

beforeEach(() => {
  tmpDir = mkdtempSync(join(tmpdir(), 'scenario-store-lifecycle-'));
  vi.resetModules();
});

afterEach(() => {
  rmSync(tmpDir, { recursive: true, force: true });
  vi.restoreAllMocks();
});

describe('memory service — scenario outcomes store lifecycle', () => {
  it('lazy-creates the scenario outcomes store at most once across many record calls', async () => {
    const closeSpy = vi.fn();
    const recordSpy = vi.fn();
    const createSpy = vi.fn(() => ({
      recordPrediction: recordSpy,
      close: closeSpy,
    }));

    vi.doMock('../src/services/memory/scenario-outcomes.js', () => ({
      createScenarioOutcomeStore: createSpy,
    }));

